param([Parameter(Mandatory=$true)][string]$RunId)
$ErrorActionPreference='Stop'
if($RunId -notmatch '^[a-z0-9][a-z0-9-]{2,62}$'){throw 'invalid run ID'}
$root=(Resolve-Path '.').Path; $dir=Join-Path $root "docs/tasks/T03-B1/evidence/$RunId"; New-Item -ItemType Directory -Force $dir|Out-Null
$appName="bewt-covext-bludit-$RunId"; $browserName="bewt-covext-bludit-selenium-$RunId"; $netName="$appName-net"
$appRef='bludit/docker:2.3.4@sha256:fa1bfd57ced7638676cef221907cc43d14ec37aa2393e57f2ddd925df3f4fae9'; $browserRef='selenium/standalone-chrome:4.34.0@sha256:bcb1d054f3c88ef618cd92a8124d894038fb5f670bf7d427f5e5bbb60882b6f6'
$labels=@('project=bewt-covext','owner=bewt-covext','managed-by=bewt-covext-agent','app=bludit','task=t03b1-g0',"runId=$RunId")
if(@(docker ps -aq --filter "label=runId=$RunId").Count -or @(docker network ls -q --filter "label=runId=$RunId").Count -or @(docker volume ls -q --filter "label=runId=$RunId").Count){throw 'run ID already owns existing resources'}
$baseline=[ordered]@{timestamp=(Get-Date).ToString('o');containers=@(docker ps -aq --no-trunc);networks=@(docker network ls -q --no-trunc);volumes=@(docker volume ls -q);images=@(docker image ls -q --no-trunc|Sort-Object -Unique)}
$baseline|ConvertTo-Json -Depth 5|Set-Content (Join-Path $dir 'docker-before.json') -Encoding utf8
$owned=[ordered]@{runId=$RunId;imageDigest='sha256:fa1bfd57ced7638676cef221907cc43d14ec37aa2393e57f2ddd925df3f4fae9';browserImageDigest='sha256:bcb1d054f3c88ef618cd92a8124d894038fb5f670bf7d427f5e5bbb60882b6f6';containers=@();network=$null}
function Save-Owned { $owned|ConvertTo-Json -Depth 6|Set-Content (Join-Path $dir 'owned-resources.json') -Encoding utf8 }
$rng=[Security.Cryptography.RandomNumberGenerator]::Create();$bytes=New-Object byte[] 16;$rng.GetBytes($bytes);$env:BLUDIT_TEST_PASSWORD=([BitConverter]::ToString($bytes).Replace('-',''))+'Aa1!';$rng.Dispose();$scriptFailed=0
try {
 $na=@('network','create','--driver','bridge');foreach($l in $labels){$na+=@('--label',$l)};$na+=$netName;$o=& docker @na 2>&1;$ec=$LASTEXITCODE;$o|Set-Content (Join-Path $dir 'docker-network-create.log') -Encoding utf8;if($ec){throw 'network creation failed'};$owned.network=@{id=($o|Select-Object -Last 1).ToString().Trim();name=$netName};Save-Owned
 $aa=@('run','--detach','--name',$appName,'--network',$netName,'--publish','127.0.0.1::80');foreach($l in $labels){$aa+=@('--label',$l)};$aa+=$appRef;$o=& docker @aa 2>&1;$ec=$LASTEXITCODE;$o|Set-Content (Join-Path $dir 'docker-start-app.log') -Encoding utf8;if($ec){throw 'app startup failed'};$owned.containers+=@(@{id=($o|Select-Object -Last 1).ToString().Trim();name=$appName;imageRef=$appRef});Save-Owned
 $ba=@('run','--detach','--name',$browserName,'--network',$netName,'--publish','127.0.0.1::4444','--shm-size=2g');foreach($l in $labels){$ba+=@('--label',$l)};$ba+=$browserRef;$o=& docker @ba 2>&1;$ec=$LASTEXITCODE;$o|Set-Content (Join-Path $dir 'docker-start-browser.log') -Encoding utf8;if($ec){throw 'browser startup failed'};$owned.containers+=@(@{id=($o|Select-Object -Last 1).ToString().Trim();name=$browserName;imageRef=$browserRef});Save-Owned
 $portsApp=(docker port $appName '80/tcp'|Select-Object -First 1).Split(':')[-1];$portsBrowser=(docker port $browserName '4444/tcp'|Select-Object -First 1).Split(':')[-1];@{appName=$appName;browserName=$browserName;appHostPort=$portsApp;browserHostPort=$portsBrowser;appUrl="http://$appName/admin";webdriverUrl="http://127.0.0.1:$portsBrowser/wd/hub"}|ConvertTo-Json|Set-Content (Join-Path $dir 'runtime-endpoints.json') -Encoding utf8
 $appOK=$false;$webdriverOK=$false;for($i=0;$i -lt 45;$i++){$code=curl.exe --silent --output NUL --write-out '%{http_code}' "http://127.0.0.1:$portsApp/admin" 2>$null;if($code -match '^(200|301|302|303)$'){$appOK=$true;break};Start-Sleep -Seconds 1};for($i=0;$i -lt 45;$i++){try{$j=(curl.exe --silent "http://127.0.0.1:$portsBrowser/status"|ConvertFrom-Json);if($j.value.ready){$webdriverOK=$true;break}}catch{};Start-Sleep -Seconds 1};@{appReady=$appOK;seleniumReady=$webdriverOK;appHttpStatus=$code;checkedAt=(Get-Date).ToString('o')}|ConvertTo-Json|Set-Content (Join-Path $dir 'readiness.json') -Encoding utf8;if(!$appOK -or !$webdriverOK){throw 'app or Selenium readiness blocked'}
 $appId=$owned.containers[0].id;$version=& docker exec $appId sh -lc 'grep -Rhn "define.*BLUDIT_VERSION" /usr/share/nginx/html/bl-kernel 2>/dev/null | head -5';$version|Set-Content (Join-Path $dir 'observed-container-version.txt') -Encoding utf8
 $reports=Join-Path $dir 'surefire-raw';New-Item -ItemType Directory -Force $reports|Out-Null;$appUrl="http://$appName/admin";$webdriverUrl="http://127.0.0.1:$portsBrowser/wd/hub"
  $targetReports='experiments/bludit/bewt-suite/target/surefire-reports';New-Item -ItemType Directory -Force $targetReports|Out-Null;Remove-Item (Join-Path $targetReports 'TEST-tests.Installer.xml'),(Join-Path $targetReports 'tests.Installer.txt') -Force -ErrorAction SilentlyContinue;$ErrorActionPreference='Continue';& mvn -B -f experiments/bludit/bewt-suite/pom.xml '-Dtest=tests.Installer' "-Dapp.url=$appUrl" "-Dwebdriver.remoteUrl=$webdriverUrl" "-Dsurefire.reportsDirectory=$reports" test *> (Join-Path $dir 'maven-installer.log');$installerCode=$LASTEXITCODE;Copy-Item (Join-Path $targetReports 'TEST-tests.Installer.xml') $reports -Force;Copy-Item (Join-Path $targetReports 'tests.Installer.txt') $reports -Force
 $pageBefore=curl.exe --silent --show-error "http://127.0.0.1:$portsApp/";if($LASTEXITCODE -ne 0){throw 'homepage probe failed after installation'};$beforePresent=[bool]($pageBefore -match [regex]::Escape('Test Content'));$pageBefore|Set-Content (Join-Path $dir 'homepage-before.html') -Encoding utf8;$before=@{present=$beforePresent;pageSha256=(Get-FileHash (Join-Path $dir 'homepage-before.html') -Algorithm SHA256).Hash;checkedAt=(Get-Date).ToString('o')};$before|ConvertTo-Json|Set-Content (Join-Path $dir 'sentinel-state-before-test.json') -Encoding utf8;if($beforePresent){throw 'Test Content sentinel already exists after install'}
  Remove-Item (Join-Path $targetReports 'TEST-tests.AddContentTest.xml'),(Join-Path $targetReports 'tests.AddContentTest.txt') -Force -ErrorAction SilentlyContinue;$ErrorActionPreference='Continue';& mvn -B -f experiments/bludit/bewt-suite/pom.xml '-Dtest=tests.AddContentTest' "-Dapp.url=$appUrl" "-Dwebdriver.remoteUrl=$webdriverUrl" "-Dsurefire.reportsDirectory=$reports" test *> (Join-Path $dir 'maven-business.log');$businessCode=$LASTEXITCODE;Copy-Item (Join-Path $targetReports 'TEST-tests.AddContentTest.xml') $reports -Force;Copy-Item (Join-Path $targetReports 'tests.AddContentTest.txt') $reports -Force;$ErrorActionPreference='Stop'
 $pageAfter=curl.exe --silent --show-error "http://127.0.0.1:$portsApp/";if($LASTEXITCODE -ne 0){throw 'homepage probe failed after business test'};$afterPresent=[bool]($pageAfter -match [regex]::Escape('Test Content'));$pageAfter|Set-Content (Join-Path $dir 'homepage-after.html') -Encoding utf8;$after=@{present=$afterPresent;pageSha256=(Get-FileHash (Join-Path $dir 'homepage-after.html') -Algorithm SHA256).Hash;checkedAt=(Get-Date).ToString('o')};$after|ConvertTo-Json|Set-Content (Join-Path $dir 'sentinel-state-after-test.json') -Encoding utf8
  $xml=Get-ChildItem $reports -Filter 'TEST-*.xml'|ForEach-Object{([xml](Get-Content $_.FullName -Raw)).DocumentElement};$summary=[ordered]@{tests=0;failures=0;errors=0;skipped=0};foreach($s in $xml){foreach($k in @('tests','failures','errors','skipped')){$summary[$k]+=[int]$s.GetAttribute($k)}};$summary|ConvertTo-Json|Set-Content (Join-Path $dir 'junit-summary.json') -Encoding utf8
 [ordered]@{installerCommand='mvn -B -f experiments/bludit/bewt-suite/pom.xml -Dtest=tests.Installer -Dapp.url=<run-local-url>/admin -Dwebdriver.remoteUrl=<loopback-selenium>/wd/hub -Dsurefire.reportsDirectory=<evidence>/surefire-raw test';installerExitCode=$installerCode;businessCommand='mvn -B -f experiments/bludit/bewt-suite/pom.xml -Dtest=tests.AddContentTest -Dapp.url=<run-local-url>/admin -Dwebdriver.remoteUrl=<loopback-selenium>/wd/hub -Dsurefire.reportsDirectory=<evidence>/surefire-raw test';businessExitCode=$businessCode;summary=$summary;sentinelBefore=$before;sentinelAfter=$after}|ConvertTo-Json -Depth 6|Set-Content (Join-Path $dir 'maven-and-sentinel-result.json') -Encoding utf8
 if($installerCode -ne 0 -or $businessCode -ne 0 -or $summary.tests -ne 2 -or $summary.failures -ne 0 -or $summary.errors -ne 0 -or $summary.skipped -ne 0 -or !$afterPresent){throw 'Maven/JUnit/sentinel acceptance failed'};Write-Output 'RUNTIME_TESTS_PASS'
} catch {$scriptFailed=1;$_|Out-String|Set-Content (Join-Path $dir 'run-error.txt') -Encoding utf8;Write-Output ('RUN_BLOCKED: '+$_.Exception.Message)} finally {
 Remove-Item Env:\BLUDIT_TEST_PASSWORD -ErrorAction SilentlyContinue
 if($owned.network){Save-Owned;$cleanupArgs=@('node','--experimental-strip-types','experiments/bludit/tools/cleanup-run.mjs',(Join-Path $dir 'owned-resources.json'),(Join-Path $dir 'docker-before.json'),(Join-Path $dir 'cleanup-result.json'));& $cleanupArgs[0] $cleanupArgs[1..($cleanupArgs.Length-1)] *> (Join-Path $dir 'cleanup-console.log');$cleanupCode=$LASTEXITCODE;if($cleanupCode -ne 0){$scriptFailed=1;Write-Output 'CLEANUP_BLOCKED';Get-Content (Join-Path $dir 'cleanup-console.log') -Tail 10}else{Write-Output 'CLEANUP_PASS'}}
}
if($scriptFailed){exit 1}
